  var en = document.getElementById('langEn');

  function apply(lang){
    var isAr = lang === 'ar';
    html.setAttribute('lang', lang);
    html.setAttribute('dir', isAr ? 'rtl' : 'ltr');
    ar.classList.toggle('active', isAr);
    en.classList.toggle('active', !isAr);
    ar.setAttribute('aria-pressed', isAr ? 'true' : 'false');
    en.setAttribute('aria-pressed', isAr ? 'false' : 'true');
  }

